  // General summary (e.g. "orders last week", "how many orders")
  if (/order.*(last week|past week|7 days)/i.test(s) || /(last week|past week).*order/i.test(s) || /how many orders|total orders/i.test(s)) {
    return { type:'orders_last_week' };
  }
  if (/total revenue|how much.*earn/i.test(s)) return { type:'total_revenue' };

