function HudRing({ size, duration, delay, opacity, dashed }) {
  return (
    <div
      style={{
        position:'absolute',
        width: size, height: size,
        borderRadius:'50%',
        border: dashed
          ? '1px dashed rgba(255,180,40,0.25)'
          : '1px solid rgba(255,180,40,0.18)',
        animation: `nova-spin ${duration}s linear ${delay}s infinite`,
        pointerEvents:'none', zIndex:2,
        boxShadow:'0 0 20px rgba(255,160,20,0.06)',
      }}
    />
  );
}

